param(
    [string]$RepoRoot = ".",
    [string]$JsonOut = "",
    [string]$SummaryOut = "",
    [switch]$FailOnIncomplete
)

$ErrorActionPreference = "Stop"
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

function Resolve-RepoPath {
    param([string]$Path)
    return (Resolve-Path -LiteralPath $Path).Path
}

function Resolve-OutputPath {
    param([string]$Path, [string]$Base)
    if ([string]::IsNullOrWhiteSpace($Path)) { return "" }
    if ([System.IO.Path]::IsPathRooted($Path)) { return $Path }
    return Join-Path $Base $Path
}

function Read-Text {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { throw "required file not found: $Path" }
    return [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
}

function Write-Text {
    param([string]$Path, [string]$Text)
    $parent = Split-Path -Parent $Path
    if ($parent) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
    [System.IO.File]::WriteAllText($Path, $Text, $utf8NoBom)
}

function Get-AstNodeKinds {
    param([string]$AstText)
    $m = [regex]::Match($AstText, 'enum\s+class\s+NK\s*\{(?<body>.*?)\};', [System.Text.RegularExpressions.RegexOptions]::Singleline)
    if (-not $m.Success) { throw "could not find enum class NK in ast.hpp" }
    $nodes = New-Object System.Collections.Generic.List[string]
    foreach ($line in ($m.Groups["body"].Value -split "`n")) {
        $clean = ($line -replace '//.*$', '').Trim()
        if ([string]::IsNullOrWhiteSpace($clean)) { continue }
        foreach ($part in ($clean -split ",")) {
            $name = $part.Trim()
            if ($name -match '^[A-Za-z_][A-Za-z0-9_]*$') { $nodes.Add($name) | Out-Null }
        }
    }
    return @($nodes)
}

function New-NodeAudit {
    param(
        [string]$Node,
        [string]$Kind,
        [string]$JsStatus,
        [string]$WasmStatus,
        [string]$JsEvidence,
        [string]$WasmEvidence,
        [string]$NextAction
    )
    return [pscustomobject]@{
        node = $Node
        kind = $Kind
        js_status = $JsStatus
        wasm_status = $WasmStatus
        js_evidence = $JsEvidence
        wasm_evidence = $WasmEvidence
        complete = (($JsStatus -in @("full", "ignored")) -and ($WasmStatus -in @("full", "ignored")))
        next_action = $NextAction
    }
}

function Status-Counts {
    param($Audits, [string]$Property)
    $full = 0
    $ignored = 0
    $partial = 0
    $missing = 0
    $unknown = 0
    foreach ($audit in $Audits) {
        $prop = $audit.PSObject.Properties[$Property]
        $value = if ($null -eq $prop) { "unknown" } else { [string]$prop.Value }
        switch ($value) {
            "full" { $full++; break }
            "ignored" { $ignored++; break }
            "partial" { $partial++; break }
            "missing" { $missing++; break }
            default { $unknown++; break }
        }
    }
    return [ordered]@{
        full = $full
        ignored = $ignored
        partial = $partial
        missing = $missing
        unknown = $unknown
        complete = ($partial -eq 0 -and $missing -eq 0 -and $unknown -eq 0)
    }
}

$root = Resolve-RepoPath $RepoRoot
$artifactRoot = Join-Path $root "artifacts"
if ([string]::IsNullOrWhiteSpace($JsonOut)) { $JsonOut = Join-Path $artifactRoot "target_lowering_audit.json" }
else { $JsonOut = Resolve-OutputPath $JsonOut $root }
if ([string]::IsNullOrWhiteSpace($SummaryOut)) { $SummaryOut = Join-Path $artifactRoot "target_lowering_audit.md" }
else { $SummaryOut = Resolve-OutputPath $SummaryOut $root }

$astPath = Join-Path $root "ast.hpp"
$parserPath = Join-Path $root "parser.hpp"
$mainPath = Join-Path $root "main.cpp"
$jsPath = Join-Path $root "tools/sura_to_js.ps1"
$jsSmokePath = Join-Path $root "tools/sura_js_target_smoke.ps1"
$wasmPath = Join-Path $root "tools/sura_to_wasm.ps1"
$astText = Read-Text $astPath
$parserText = Read-Text $parserPath
$mainText = Read-Text $mainPath
$jsText = Read-Text $jsPath
$jsSmokeText = Read-Text $jsSmokePath
$wasmText = Read-Text $wasmPath
$astNodes = @(Get-AstNodeKinds $astText)

$map = @{}
function Add-Node {
    param([string]$Node, [string]$Kind, [string]$JsStatus, [string]$WasmStatus, [string]$JsEvidence, [string]$WasmEvidence, [string]$NextAction)
    $script:map[$Node] = New-NodeAudit $Node $Kind $JsStatus $WasmStatus $JsEvidence $WasmEvidence $NextAction
}

