$audits = New-Object System.Collections.Generic.List[object]
$unknownNodes = New-Object System.Collections.Generic.List[string]
foreach ($node in $astNodes) {
    if ($map.ContainsKey($node)) {
        $audits.Add($map[$node]) | Out-Null
    } else {
        $unknownNodes.Add($node) | Out-Null
        $audits.Add((New-NodeAudit $node "unknown" "unknown" "unknown" "unclassified AST node" "unclassified AST node" "classify and lower this AST node in target audit")) | Out-Null
    }
}

$jsSourceLineFrontend = ($jsText -match 'foreach\s*\(\$raw\s+in\s+\$rawSourceLines\)')
$wasmSourceLineFrontend = ($wasmText -match '\$rawLines\s*=\s*@\(Expand-WasmSourceLines' -or
    $wasmText -match 'Compile-Lines\s+\$fn\.Body' -or
    $wasmText -match 'Compile-Lines\s+@\(\$mainLines\)')
$astJsonExport = ($mainText -match '--ast-json' -and $mainText -match 'sura\.ast\.v1' -and $mainText -match 'sura_ast_json')
$jsAstJsonInput = ($jsText -match '\[switch\]\$AstJson' -and $jsText -match 'Convert-JsAstExpr' -and $jsText -match 'AST JSON input: sura\.ast\.v1')
$jsAstImportExpansion = ($jsText -match 'Expand-JsAstImports' -and $jsText -match 'Export-JsAstReport' -and $jsText -match 'cyclic JS AST import')
$jsAstFullTargetSmoke = ($jsAstJsonInput -and $jsSmokeText -match 'full JS target AST JSON' -and $jsSmokeText -match 'test_js_target\.ast\.json' -and $jsSmokeText -match 'js target: PASS')
$wasmAstJsonInput = ($wasmText -match '\[switch\]\$AstJson' -and $wasmText -match 'Convert-WasmAstExpr' -and $wasmText -match 'AST JSON input: sura\.ast\.v1')
$wasmAstImportExpansion = ($wasmText -match 'Expand-WasmAstImports' -and $wasmText -match 'Export-WasmAstReport' -and $wasmText -match 'cyclic WASM AST import')
$wasmWatInstructionBoundaryGuard = ($wasmText -match 'Assert-WasmWatInstructionBoundaries' -and $wasmText -match 'invalid WASM WAT instruction boundary')
$astOrBytecodeFrontend = ($jsAstFullTargetSmoke -and -not $wasmSourceLineFrontend)
$auditArray = @($audits.ToArray())
$jsCounts = Status-Counts $auditArray "js_status"
$wasmCounts = Status-Counts $auditArray "wasm_status"
$classificationComplete = ($unknownNodes.Count -eq 0)
$loweringComplete = ([bool]$jsCounts.complete -and [bool]$wasmCounts.complete -and $astOrBytecodeFrontend)
$status = if ($loweringComplete) { "COMPLETE" } else { "INCOMPLETE" }
$incompleteNodes = @($audits | Where-Object { -not $_.complete })
$jsFrontend = if ($jsAstFullTargetSmoke -and $jsSourceLineFrontend) { "AST JSON full-target path plus source-line compatibility" } elseif ($jsAstFullTargetSmoke) { "AST JSON full-target path" } elseif ($jsSourceLineFrontend) { "source-line transpiler" } else { "AST/bytecode frontend" }
$wasmFrontend = if ($wasmAstJsonInput -and $wasmSourceLineFrontend) { "AST JSON numeric subset plus source-line numeric fallback" } elseif ($wasmSourceLineFrontend) { "source-line numeric subset transpiler" } elseif ($wasmAstJsonInput) { "AST JSON frontend for source and AST JSON input" } else { "AST/bytecode frontend" }
$pipelineBlocker = if (-not $astOrBytecodeFrontend) {
    if (-not $jsAstFullTargetSmoke) { "Full AST/bytecode lowering is not complete while JS lacks a full-target AST/bytecode smoke." }
    else { "Full AST/bytecode lowering is not complete while WASM still reads source lines directly." }
} elseif (-not [bool]$wasmCounts.complete) {
    "WASM now uses the AST JSON frontend, but dynamic Value/function/class/exception node lowering is still partial."
} else {
    ""
}
$classifiedNodeCount = $astNodes.Count - $unknownNodes.Count
$unknownNodeArray = @($unknownNodes.ToArray())

$report = [ordered]@{
    schema = "sura.target.lowering_audit.v1"
    generated_utc = [DateTime]::UtcNow.ToString("o")
    passed = $classificationComplete
    status = $status
    lowering_complete = $loweringComplete
    ast_node_count = $astNodes.Count
    classified_node_count = $classifiedNodeCount
    unknown_nodes = $unknownNodeArray
    pipeline = [ordered]@{
        ast_or_bytecode_frontend = $astOrBytecodeFrontend
        ast_json_export = $astJsonExport
        js_ast_json_input = $jsAstJsonInput
        js_ast_import_expansion = $jsAstImportExpansion
        js_ast_full_target_smoke = $jsAstFullTargetSmoke
        wasm_ast_json_input = $wasmAstJsonInput
        wasm_ast_import_expansion = $wasmAstImportExpansion
        wasm_wat_instruction_boundary_guard = $wasmWatInstructionBoundaryGuard
        js_frontend = $jsFrontend
        wasm_frontend = $wasmFrontend
        blocker = $pipelineBlocker
    }
    js = $jsCounts
    wasm = $wasmCounts
    incomplete_node_count = $incompleteNodes.Count
    node_audits = $auditArray
    next_actions = @(
        "Finish upgrading partial WASM AST nodes from numeric/hinted lowering to full dynamic Value semantics.",
        "Wire the tagged dynamic Value ABI fully into WASM AST lowering for strings, nil, dicts, objects, function values, classes, and exceptions.",
        "Keep this audit in CI/release evidence so target parity gaps cannot be hidden by passing subset smoke tests."
    )
}

Write-Text $JsonOut ($report | ConvertTo-Json -Depth 8)

$lines = New-Object System.Collections.Generic.List[string]
$lines.Add("# Sura Target Lowering Audit") | Out-Null
$lines.Add("") | Out-Null
$lines.Add("Generated UTC: $($report.generated_utc)") | Out-Null
$lines.Add("Status: $status") | Out-Null
$lines.Add("AST nodes: $($report.ast_node_count)") | Out-Null
$lines.Add("JS full/partial/missing/ignored: $($jsCounts.full)/$($jsCounts.partial)/$($jsCounts.missing)/$($jsCounts.ignored)") | Out-Null
$lines.Add("WASM full/partial/missing/ignored: $($wasmCounts.full)/$($wasmCounts.partial)/$($wasmCounts.missing)/$($wasmCounts.ignored)") | Out-Null
$lines.Add("") | Out-Null
$lines.Add("## Pipeline") | Out-Null
$lines.Add("- JS frontend: $($report.pipeline.js_frontend)") | Out-Null
$lines.Add("- WASM frontend: $($report.pipeline.wasm_frontend)") | Out-Null
$lines.Add("- AST JSON export: $($report.pipeline.ast_json_export)") | Out-Null
$lines.Add("- JS AST JSON input: $($report.pipeline.js_ast_json_input)") | Out-Null
$lines.Add("- JS AST import expansion: $($report.pipeline.js_ast_import_expansion)") | Out-Null
$lines.Add("- JS full AST target smoke: $($report.pipeline.js_ast_full_target_smoke)") | Out-Null
$lines.Add("- WASM AST JSON input: $($report.pipeline.wasm_ast_json_input)") | Out-Null
$lines.Add("- WASM AST import expansion: $($report.pipeline.wasm_ast_import_expansion)") | Out-Null
$lines.Add("- WASM WAT instruction-boundary guard: $($report.pipeline.wasm_wat_instruction_boundary_guard)") | Out-Null
$lines.Add("- Full AST/bytecode frontend: $($report.pipeline.ast_or_bytecode_frontend)") | Out-Null
$lines.Add("") | Out-Null
$lines.Add("## Partial Or Missing Nodes") | Out-Null
$lines.Add("") | Out-Null
$lines.Add("| Node | Kind | JS | WASM | Next action |") | Out-Null
$lines.Add("| --- | --- | --- | --- | --- |") | Out-Null
foreach ($item in $incompleteNodes) {
    $next = ([string]$item.next_action).Replace("|", "/")
    $lines.Add("| $($item.node) | $($item.kind) | $($item.js_status) | $($item.wasm_status) | $next |") | Out-Null
}
Write-Text $SummaryOut ($lines -join "`n")

Write-Host ("target_lowering_audit: {0} (JS partial/missing {1}/{2}, WASM partial/missing {3}/{4})" -f $status, $jsCounts.partial, $jsCounts.missing, $wasmCounts.partial, $wasmCounts.missing)
if (-not $classificationComplete) {
    throw "target lowering audit has unclassified AST nodes: $($unknownNodes -join ', ')"
}
if ($FailOnIncomplete -and -not $loweringComplete) {
    throw "target lowering incomplete: JS/WASM are not fully AST/bytecode lowered"
}
